// single-item input: the config node emits exactly one row.
const cfg = $input.first().json;

const role = String(cfg.role_keyword || '').trim();
const location = String(cfg.location || '').trim();
if (!role || !location) {
  throw new Error('Set both role_keyword and location in ' + 'Set Market Config' + '.');
}

// Bright Data discovers by keyword, so the payload is the search itself rather
// than a list of URLs. One search per run keeps the ranking about one market.
const payload = [{
  keyword: role,
  location,
  country: String(cfg.country || 'US').toUpperCase(),
  time_range: cfg.time_range || 'Past month',
  job_type: cfg.job_type || 'Full-time',
}];

return [{ json: { payload, role, location, scanned_at: new Date().toISOString() } }];

// single-item input: the trigger endpoint answers once with one snapshot id.
const res = $input.first().json;

// Bright Data answers validation errors with HTTP 200 and an error body, and
// this node runs with neverError, so an unchecked response looks like a success
// and fails several nodes later blaming the wrong thing.
if (res.error || res.errors) {
  throw new Error('Bright Data rejected the search: ' + JSON.stringify(res.error || res.errors));
}
if (!res.snapshot_id) {
  throw new Error('No snapshot_id in the Bright Data response: ' + JSON.stringify(res).slice(0, 400));
}

return [{ json: { snapshot_id: res.snapshot_id } }];

const MAX_POLLS = 20; // 20 x 20s = about 7 minutes

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check Discovery Accepted').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'Snapshot ' + snapshotId + ' still ' + res.status + ' after ' + attempt +
    ' polls. Raise MAX_POLLS or narrow the search.'
  );
}

return [{ json: { status: res.status, snapshot_id: snapshotId, attempt, records: res.records || 0 } }];

const cfg = $('Set Market Config').first().json;
const maxChars = 2500;

// A post with no description gives the extractor nothing to read, and an empty
// extraction still costs a model call, so drop those here.
const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  if (j.error || j.warning) continue;

  const id = String(j.job_posting_id || j.url || '');
  if (!id || seen.has(id)) continue;
  seen.add(id);

  const summary = String(j.job_summary || '').replace(/\s+/g, ' ').trim();
  if (summary.length < 200) continue;

  // Descriptions run to 10,000 characters. The requirements live near the top,
  // so a head slice keeps the model cost roughly flat per post.
  const text = summary.length > maxChars ? summary.slice(0, maxChars) : summary;

  // Compensation is stated near the bottom - it sat between characters 4,000 and
  // 9,000 on every post that had it - so the head slice above throws away the
  // one sentence the pay question depends on. Carry it separately.
  const payMatch = summary.match(
    /[^.]{0,130}(?:salary|compensation|base pay|pay range|hourly rate)[^.]{0,170}/i
  );

  const bs = j.base_salary || null;
  const statedPay = bs && bs.min_amount
    ? `${bs.currency || '$'}${bs.min_amount} - ${bs.currency || '$'}${bs.max_amount} per ${bs.payment_period || 'yr'}`
    : '';

  out.push({
    json: {
      job_id: id,
      title: String(j.job_title || '').trim(),
      company: String(j.company_name || '').trim(),
      location: String(j.job_location || '').trim(),
      seniority: String(j.job_seniority_level || '').trim(),
      employment_type: String(j.job_employment_type || '').trim(),
      industry: String(j.job_industries || '').trim(),
      applicants: Number(j.job_num_applicants || 0),
      posted: String(j.job_posted_date || '').slice(0, 10),
      url: String(j.url || '').split('?')[0],
      stated_pay: statedPay,
      pay_text: payMatch ? payMatch[0].trim() : '',
      // Bright Data's own structured pay, kept as numbers so the ranking can
      // prefer it over the model's reading of the prose.
      struct_pay_min: bs && bs.min_amount ? Number(bs.min_amount) : 0,
      struct_pay_max: bs && bs.max_amount ? Number(bs.max_amount) : 0,
      struct_pay_period: bs && bs.payment_period ? String(bs.payment_period) : '',
      description: text,
      role: cfg.role_keyword,
      market: cfg.location,
    },
  });
}

if (!out.length) {
  throw new Error(
    'No usable job posts came back. Widen time_range, or check that the ' +
    'keyword and location match a real LinkedIn search.'
  );
}

return out;

parameters.text:
=Extract the requirements from this job posting.

For `skills`, name at most 10 concrete, checkable skills and tools: named
software (hubspot, salesforce, ga4, figma, snowflake), named techniques (seo,
paid search, sql, a/b testing, lifecycle marketing) and named languages. Use the
short common name in lower case. Do not return responsibilities, seniority
words, soft skills or whole phrases from the advert: "relationship building",
"cross-functional collaboration", "strategy" and "ownership" are all wrong.

For pay, read the description text as well as the structured field. Set
`pay_disclosed` false when the posting states no figure, and never guess a range.
Report the pay exactly as written, and set `pay_period` to match it.

Job title: {{ $json.title }}
Company: {{ $json.company }}
Seniority label: {{ $json.seniority }}
Pay stated in structured data: {{ $json.stated_pay || 'none' }}
Pay sentence found in the description: {{ $json.pay_text || 'none' }}

Description:
{{ $json.description }}

parameters.jsCode:
const cfg = $('Set Market Config').first().json;
const posts = $('Normalise Job Posts').all().map((i) => i.json);
// The extractor nests its result under `output` on some versions. Reading the
// item directly gives undefined skills on every post, which produces an empty
// ranking on a run where every node is green.
const extracted = $input.all().map((i) => (i.json && i.json.output) || i.json || {});

// Merge each extraction back onto the post it came from. The extractor emits one
// item per input item in the same order, so index alignment is the join key.
const rows = posts.map((p, i) => ({ ...p, ...(extracted[i] || {}) }));

// --- skills -------------------------------------------------------------
// Post counts, not mention counts. A post that says "SQL" six times is still one
// employer asking for SQL, and counting mentions would let one verbose ad
// dominate the ranking.
const ALIAS = {
  'js': 'javascript', 'ts': 'typescript', 'py': 'python',
  'postgres': 'postgresql', 'k8s': 'kubernetes', 'gcp': 'google cloud',
  'aws cloud': 'aws', 'ga4': 'google analytics', 'node': 'node.js',
};
const clean = (s) => {
  let t = String(s || '').toLowerCase().trim()
    .replace(/[.,;:()]+$/g, '')
    .replace(/\s+/g, ' ');
  return ALIAS[t] || t;
};

const perPost = rows.map(
  (r) => new Set((r.skills || []).map(clean).filter((s) => s.length > 1 && s.length < 40))
);

// "automation" from one posting and "automation workflows" from another are one
// demand signal, not two. Collapse the longer name onto the shorter one, but
// only when that shorter name is itself something an employer wrote, so the
// ranking never shows a label nobody used. Counting has to happen after this,
// or a posting naming both variants would be counted twice.
const allNames = [...new Set(perPost.flatMap((s) => [...s]))].sort((a, b) => a.length - b.length);
const canon = new Map();
for (const name of allNames) {
  const shorter = allNames.find((s) => s.length < name.length && name.startsWith(s + ' '));
  canon.set(name, shorter ? canon.get(shorter) || shorter : name);
}

const skillPosts = new Map();
for (const set of perPost) {
  const uniq = new Set([...set].map((s) => canon.get(s) || s));
  for (const s of uniq) skillPosts.set(s, (skillPosts.get(s) || 0) + 1);
}

const total = rows.length;

// On a real scan of 25 postings a skill named by one employer is noise, not
// demand, and those one-offs otherwise fill the whole ranking. On a small sample
// there is nothing to spare, so the floor only applies once the sample is big
// enough for it to mean something.
const floor = total >= 10 ? 2 : 1;

const skills = [...skillPosts.entries()]
  .filter(([, posts_requiring]) => posts_requiring >= floor)
  .map(([skill, posts_requiring]) => ({
    skill,
    posts_requiring,
    share_pct: Math.round((posts_requiring / total) * 1000) / 10,
  }))
  .sort((a, b) => b.posts_requiring - a.posts_requiring || a.skill.localeCompare(b.skill));

// --- pay ----------------------------------------------------------------
// Only 1 of 6 posts carried structured pay in testing, so most of this comes
// from the model reading the text. Normalise everything to an annual figure and
// throw out anything that cannot be an annual base, which is what stops a "$600"
// day rate or a stray bonus number from moving the median.
const ANNUALISE = { year: 1, month: 12, hour: 2080 };

// The period arrives as "yr" from Bright Data, "per yr" from the string handed to
// the model, and "year" from the schema, depending on which source answered.
// Matching the bare word only means every salary annualises to zero and the
// report then states that nobody disclosed pay - wrong, and wrong in a way that
// reads like a real finding.
const period = (p) => {
  const t = String(p || '').toLowerCase();
  if (/(yr|year|annual|annum|\bpa\b)/.test(t)) return 'year';
  if (/(month|\bmo\b|mth)/.test(t)) return 'month';
  if (/(hour|\bhr\b|hourly)/.test(t)) return 'hour';
  return '';
};
const annual = (v, p) => {
  const n = Number(v) || 0;
  const mult = ANNUALISE[period(p)] || 0;
  return mult ? n * mult : 0;
};

const paid = [];
for (const r of rows) {
  // Bright Data's structured field is authoritative where it exists; the model
  // reading the prose is the fallback for the postings that lack it.
  const useStruct = Boolean(r.struct_pay_min);
  if (!useStruct && !r.pay_disclosed) continue;

  const rawLo = useStruct ? r.struct_pay_min : r.pay_min;
  const rawHi = useStruct ? r.struct_pay_max : r.pay_max;
  const per = useStruct ? r.struct_pay_period : r.pay_period;

  const lo = annual(rawLo, per);
  const hi = annual(rawHi, per) || lo;
  // Anything that cannot be an annual base is noise: a day rate, a bonus figure
  // or an equity number the model mistook for salary.
  if (!lo || lo < 20000 || lo > 2000000) continue;
  paid.push({ lo, hi: Math.max(lo, hi), mid: (lo + Math.max(lo, hi)) / 2, title: r.title, company: r.company });
}

const median = (arr) => {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
};

const pay = {
  disclosed_posts: paid.length,
  total_posts: total,
  disclosure_pct: Math.round((paid.length / total) * 1000) / 10,
  low: paid.length ? Math.min(...paid.map((p) => p.lo)) : 0,
  median_mid: median(paid.map((p) => p.mid)),
  high: paid.length ? Math.max(...paid.map((p) => p.hi)) : 0,
};

// --- shape of the market ------------------------------------------------
// The model ignores the enum often enough to matter - one run came back with
// "not specified", "in-person" and "in-office" for three postings, which reads
// as three different working patterns when it is really one.
const REMOTE = (v) => {
  const t = String(v || '').toLowerCase();
  if (/hybrid/.test(t)) return 'hybrid';
  if (/remote|work from home|wfh|distributed/.test(t)) return 'remote';
  if (/on-?site|in-?person|in-?office|on premise/.test(t)) return 'onsite';
  return 'unclear';
};

const tally = (key, map) => {
  const m = {};
  for (const r of rows) {
    const v = map ? map(r[key]) : (String(r[key] || 'unclear').trim() || 'unclear');
    m[v] = (m[v] || 0) + 1;
  }
  return Object.entries(m).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({ name: k, posts: v }));
};

const years = rows.map((r) => Number(r.must_have_years) || 0).filter((y) => y > 0 && y < 30);

return [{
  json: {
    role: cfg.role_keyword,
    market: cfg.location,
    scanned_at: new Date().toISOString().slice(0, 10),
    total_posts: total,
    skills,
    pay,
    remote: tally('remote_policy', REMOTE),
    seniority: tally('seniority'),
    top_companies: tally('company').slice(0, 5),
    median_years: median(years),
    sample_titles: [...new Set(rows.map((r) => r.title))].slice(0, 6),
  },
}];

const current = $('Rank Skills And Pay').first().json;

// The sheet read runs with alwaysOutputData, so on the very first run this is a
// single empty item rather than no items. Treat that as "no history" instead of
// letting an undefined row through as a real previous scan.
const history = $input.all()
  .map((i) => i.json || {})
  .filter((r) => r && r.skill && r.scanned_at);

const sameMarket = history.filter(
  (r) => String(r.role) === String(current.role) && String(r.market) === String(current.market)
);

const dates = [...new Set(sameMarket.map((r) => String(r.scanned_at)))]
  .filter((d) => d !== current.scanned_at)
  .sort();
const previousDate = dates.length ? dates[dates.length - 1] : null;

const prev = new Map();
if (previousDate) {
  for (const r of sameMarket.filter((r) => String(r.scanned_at) === previousDate)) {
    prev.set(String(r.skill), Number(r.share_pct) || 0);
  }
}

const TOP = 15;
const top = current.skills.slice(0, TOP);

const movement = top.map((s) => {
  const before = prev.has(s.skill) ? prev.get(s.skill) : null;
  const delta = before === null ? null : Math.round((s.share_pct - before) * 10) / 10;
  let status = 'steady';
  if (before === null) status = previousDate ? 'new' : 'first scan';
  else if (delta >= 5) status = 'rising';
  else if (delta <= -5) status = 'falling';
  return { ...s, previous_pct: before, delta_pct: delta, status };
});

// Skills that were in the previous top list and are not in this one at all.
const nowHas = new Set(current.skills.map((s) => s.skill));
const dropped = [...prev.entries()]
  .filter(([skill]) => !nowHas.has(skill))
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([skill, share_pct]) => ({ skill, share_pct }));

return [{ json: { ...current, previous_scan: previousDate, movement, dropped } }];

parameters.text:
=You are a labour market analyst. Write a short brief for someone deciding what this role needs to know and what it should pay.

Role: {{ $json.role }}
Market: {{ $json.market }}
Job postings analysed: {{ $json.total_posts }}
Previous scan: {{ $json.previous_scan || 'none, this is the first scan' }}
Most-demanded skills with the share of posts requiring each, and movement since the last scan: {{ JSON.stringify($json.movement) }}
Skills that dropped out since the last scan: {{ JSON.stringify($json.dropped) }}
Pay, in annual terms: {{ JSON.stringify($json.pay) }}
Working pattern: {{ JSON.stringify($json.remote) }}
Seniority mix: {{ JSON.stringify($json.seniority) }}
Typical years of experience asked for: {{ $json.median_years }}

Write 4 to 6 sentences covering: what this market clearly expects, anything that has moved since the last scan, and what the pay data does and does not support.

Be accurate about the evidence. `disclosed_posts` is how many of the posts stated pay at all; if that number is small, say the pay figures are indicative rather than reliable, and never present a median drawn from a handful of posts as the market rate. If there is no previous scan, say so instead of inventing a trend. Plain sentences, no bullet points, no headings.

parameters.jsCode:
const data = $('Compare With Last Scan').first().json;
// single-item input: the brief chain is fed one aggregated item and answers with
// one block of prose, so there is no second item to lose here.
const brief = String($input.first().json.text || $input.first().json.output || '').trim();

const money = (n) => (n ? '$' + Math.round(n / 1000) + 'k' : 'n/a');
const plural = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');

// One row per skill, so the sheet accumulates a history the next run can diff.
const rows = data.movement.map((s, i) => ({
  scanned_at: data.scanned_at,
  role: data.role,
  market: data.market,
  rank: i + 1,
  skill: s.skill,
  posts_requiring: s.posts_requiring,
  share_pct: s.share_pct,
  previous_pct: s.previous_pct === null ? '' : s.previous_pct,
  delta_pct: s.delta_pct === null ? '' : s.delta_pct,
  status: s.status,
  posts_analysed: data.total_posts,
  pay_disclosed_posts: data.pay.disclosed_posts,
  pay_low: data.pay.low || '',
  pay_median: data.pay.median_mid || '',
  pay_high: data.pay.high || '',
}));

const lines = [];
lines.push(`*${data.role} - ${data.market}*`);
lines.push(`${plural(data.total_posts, 'live posting')} analysed` +
  (data.previous_scan ? `, compared with ${data.previous_scan}.` : ', first scan so no comparison yet.'));

lines.push('');
lines.push('*Most demanded skills*');
data.movement.slice(0, 8).forEach((s, i) => {
  const move = s.delta_pct === null || s.delta_pct === 0
    ? ''
    : ` (${s.delta_pct > 0 ? '+' : ''}${s.delta_pct} pts)`;
  const tag = s.status === 'new' ? ' - new' : '';
  lines.push(`${i + 1}. ${s.skill} - ${s.share_pct}% of postings${move}${tag}`);
});

if (data.dropped.length) {
  lines.push('');
  lines.push('*Dropped out since last scan*');
  lines.push(data.dropped.map((d) => `${d.skill} (was ${d.share_pct}%)`).join(', '));
}

lines.push('');
if (data.pay.disclosed_posts) {
  lines.push('*Pay*');
  lines.push(`${money(data.pay.low)} to ${money(data.pay.high)}, midpoint ${money(data.pay.median_mid)} - ` +
    `from the ${plural(data.pay.disclosed_posts, 'posting')} that disclosed, ${data.pay.disclosure_pct}% of the sample.`);
} else {
  lines.push('*Pay*');
  lines.push('No posting in this sample stated a salary.');
}

const remote = data.remote.map((r) => `${r.name} ${r.posts}`).join(', ');
lines.push('');
lines.push(`*Working pattern* ${remote}`);
lines.push(`*Typical experience asked* ${data.median_years || 'not stated'} years`);

if (brief) {
  lines.push('');
  lines.push(brief);
}

// One item carrying both payloads. Split Out turns `rows` into one item per
// skill for the sheet; the Slack node runs once and reads `message` from here.
// Emitting the message as its own item instead would append it to the sheet as
// a row, and post the digest once per skill.
return [{ json: { message: lines.join('\n'), rows, row_count: rows.length } }];
